46	export interface CancelResult {
47	  ok: boolean;
48	  released?: boolean;
49	  error?: string;
50	}
51	
52	/**
53	 * Cancel a confirmed booking. Cancellation policy (SPEC §5): a scheduled session
54	 * cancelled ≥1h before its start releases the hold, otherwise the block is
55	 * charged. A "now" booking that was never joined releases (the customer never
56	 * talked — "you're in control, leave any time"). Capture/refund go through the
57	 * payments adapter.
58	 */
59	export async function cancelBooking(bookingId: string): Promise<CancelResult> {
60	  const profile = await requireRole("customer");
61	  if (!uuid.safeParse(bookingId).success) {
62	    return { ok: false, error: "Booking not found." };
63	  }
64	  const supabase = await createClient();
65	
66	  const { data: booking } = await supabase
67	    .from("bookings")
68	    .select("*")
69	    .eq("id", bookingId)
70	    .maybeSingle();
71	  if (!booking || booking.customer_id !== profile.id) {
72	    return { ok: false, error: "Booking not found." };
73	  }
74	  if (booking.status !== "confirmed") {
75	    return { ok: false, error: "This booking can't be cancelled." };
76	  }
77	
78	  let release: boolean;
79	  if (booking.start_mode === "scheduled") {
80	    release =
81	      cancellationOutcome({
82	        priceBlockCents: booking.price_block_cents,
83	        scheduledAt: booking.scheduled_at,
84	        nowMs: Date.now(),
85	      }).action === "release";
86	  } else {
87	    release = true; // a "now" booking that was never joined
88	  }
89	
90	  // Make the status transition the gate for the money side-effect: only the
91	  // call that actually flips confirmed → cancelled proceeds to refund/capture,
92	  // so a concurrent/retried cancel can't double-refund or double-capture.
93	  const { data: transitioned, error } = await supabase
94	    .from("bookings")
95	    .update({ status: "cancelled" })
96	    .eq("id", bookingId)
97	    .eq("customer_id", profile.id)
98	    .eq("status", "confirmed")
99	    .select("id");
100	  if (error) return { ok: false, error: "Could not cancel the booking." };
101	  if (!transitioned || transitioned.length === 0) {
102	    return { ok: false, error: "This booking can't be cancelled." };
103	  }
104	
105	  const payments = getPayments();
106	  if (booking.payment_ref) {
107	    if (release) {
108	      await payments.refund({
109	        paymentRef: booking.payment_ref,
110	        amountCents: booking.price_block_cents,
111	      });
112	    } else {
113	      await payments.capture({
114	        paymentRef: booking.payment_ref,
115	        amountCents: booking.price_block_cents,
116	      });
117	    }
118	  }
119	
120	  revalidatePath("/account");
121	  return { ok: true, released: release };
122	}
