124	const rescheduleSchema = z.object({
125	  bookingId: uuid,
126	  scheduledAt: z.string().datetime(),
127	});
128	
129	/** Move a confirmed booking to a new future time. */
130	export async function rescheduleBooking(input: {
131	  bookingId: string;
132	  scheduledAt: string;
133	}): Promise<{ ok: boolean; error?: string }> {
134	  const profile = await requireRole("customer");
135	  const parsed = rescheduleSchema.safeParse(input);
136	  if (!parsed.success) return { ok: false, error: "Pick a valid time." };
137	  if (new Date(parsed.data.scheduledAt).getTime() <= Date.now()) {
138	    return { ok: false, error: "Pick a time in the future." };
139	  }
140	
141	  const supabase = await createClient();
142	  const { error } = await supabase
143	    .from("bookings")
144	    .update({
145	      scheduled_at: parsed.data.scheduledAt,
146	      start_mode: "scheduled",
147	    })
148	    .eq("id", parsed.data.bookingId)
149	    .eq("customer_id", profile.id)
150	    .eq("status", "confirmed");
151	  if (error) return { ok: false, error: "Could not reschedule." };
152	
153	  revalidatePath("/account");
154	  return { ok: true };
155	}
